  @GetMapping
  public List<Tarefa> listar() {
    return service.listarTodas();
  }

  @GetMapping("/{id}")
  public Tarefa buscar(@PathVariable Long id) {
    return service.buscarPorId(id);
  }
}

@RestController
@RequestMapping("/api/tarefas")
public class TarefaController {

  @PostMapping
