@RestController
@RequestMapping("/api/tarefas")
public class TarefaController {

  @PutMapping("/{id}")
  public Tarefa atualizar(@PathVariable Long id,
                        @RequestBody Tarefa dados) {
    return service.atualizar(id, dados);
  }

  @DeleteMapping("/{id}")
  public void remover(@PathVariable Long id) {
    service.remover(id);
  }
}

